<template><view class="m2-page"><view class="m2-card"><text class="m2-heading">收支明细</text><text class="m2-muted">金额单位：元 · 共 {{total}} 条</text></view><view class="m2-card" v-for="item in items" :key="item.id"><view class="m2-heading"><text>{{labels[Number(item.type)]||'余额变动'}}</text><text :class="outgoing(item)?'expense':'income'">{{outgoing(item)?'−':'+'}}{{money(item.amount)}}</text></view><text class="m2-body">{{item.remark}}</text><view class="m2-row m2-muted"><text>{{date(item.createTime)}}</text><text>余额 {{money(item.balanceAfter)}}</text></view></view><text v-if="error" class="m2-error" @click="load">{{error}}（点击重试）</text><view v-if="!items.length&&!loading&&!error" class="m2-empty">还没有收支记录</view><view class="m2-link m2-center" v-if="loading||items.length<total" @click="load">{{loading?'加载中…':'加载更多'}}</view></view></template>
<script>
import {getFlows} from '../../api/wallet'
import {requireLogin} from '../../utils/auth'
import {money} from '../../utils/money'
export default{data(){return{items:[],page:1,total:0,loading:false,error:'',labels:{1:'充值入账',2:'章节购买',3:'作品打赏',4:'收到打赏',5:'章节分成',6:'余额调整',7:'VIP订阅'}}},onShow(){if(requireLogin()){this.items=[];this.page=1;this.total=0;this.load()}},methods:{money,outgoing(i){return [2,3,7].includes(Number(i.type))},date(v){return(v||'').replace('T',' ').slice(0,16)},async load(){if(this.loading)return;this.loading=true;this.error='';try{const d=await getFlows({pageNum:this.page,pageSize:20});this.items.push(...d.records);this.total=Number(d.total);this.page++}catch(e){this.error=e.msg}finally{this.loading=false}}}}
</script><style scoped>.income{color:#54836b}.expense{color:#b5533d}</style>
